import React from 'react';
import './About.css';

const About = ({ language }) => {
  const publicUrl = process.env.PUBLIC_URL || '';

  const content = {
    RU: {
      title: 'О проекте',
      p1: 'Мы — студенты Тюменского Государственного Университета. И мы решили разобраться, что на самом деле думают о Тюмени иностранные студенты.',
      p2: 'Зачем это нам? Во-первых, самим интересно. Во-вторых, стереотипы о Сибири — это не шутки. «Там холодно, опасно, делать нечего» — такие мысли реально мешают людям сюда ехать. А значит, страна теряет талантливых ребят, которые могли бы здесь остаться и работать, а иностранцы ограничивают себя от поездки в хороший город.',
      authorsTitle: 'Авторы проекта:',
      authors: [
        'Студенты ТюмГУ (курс «Основы российской государственности»):',
        '1. Ходжматов Шехроз Шухратович',
        '2. Клышников Константин Андреевич',
        '3. Горунова Антонина Андреевна',
        '4. Нагашбаева Лаура Дастановна',
        '5. Островкина Даша Ивановна'
      ]
    },
    EN: {
      title: 'About the Project',
      p1: 'We are students of Tyumen State University. And we decided to figure out what international students actually think about Tyumen.',
      p2: 'Why do we need this? First, it\'s interesting. Second, stereotypes about Siberia are no joke. "It\'s cold, dangerous, nothing to do there" — such thoughts really prevent people from coming here. This means the country loses talented youth, and foreigners limit themselves from visiting a good city.',
      authorsTitle: 'Project authors:',
      authors: [
        'Students of UTMN (Course "Fundamentals of Russian Statehood"):',
        '1. Khodzhmatov Shekhroz Shukhratovich',
        '2. Klyshnikov Konstantin Andreevich',
        '3. Gorunova Antonina Andreevna',
        '4. Nagashbaeva Laura Dastanovna',
        '5. Ostrovkina Dasha Ivanovna'
      ]
    }
  };

  const data = content[language];

  return (
    <section className="about-section section animate-in">
      <div className="container">
        <h2 className="section-title">{data.title}</h2>
        
        <div className="about-content-wrapper">
          <div className="about-text-block">
            <p>{data.p1}</p>
            <p>{data.p2}</p>
            
            <div className="authors-block">
              <h3>{data.authorsTitle}</h3>
              {/* Компактный вывод списка авторов */}
              {data.authors.map((authorLine, idx) => (
                <p key={idx} className={idx === 0 ? "authors-heading" : "author-name"}>
                  {authorLine}
                </p>
              ))}
            </div>
          </div>
          
          <div className="about-image-block">
            <img 
              src={`${publicUrl}/images/kotak_rose.webp`} 
              alt="Котеус с розой" 
              className="about-cat-rose"
              loading="lazy"
            />
          </div>
        </div>
      </div>
    </section>
  );
};

export default About;